def parse_ranges(s):
    out = []
    for part in s.split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            lo, hi = part.split('-', 1)
            out.extend(range(int(lo), int(hi) + 1))
        else:
            out.append(int(part))
    return sorted(set(out))

def top_k(nums, k):
    idx = sorted(range(len(nums)), key=lambda i: (-nums[i], i))
    return [nums[i] for i in idx[:k]]

from decimal import Decimal, ROUND_HALF_UP

def money_round(x):
