def slugify(s):
    import re
    s = s.lower()
    s = re.sub(r'[^a-z0-9]+', '-', s)
    return s.strip('-')

def parse_duration(s):
    import re
    h = re.search(r'(\d+)h', s)
    m = re.search(r'(\d+)m(?!s)', s)
    sec = re.search(r'(\d+)s', s)
    return (int(h.group(1)) * 3600 if h else 0) + (int(m.group(1)) * 60 if m else 0) + (int(sec.group(1)) if sec else 0)

def chunk_even(lst, n):
    if n <= 0:
        return []
    base, extra = divmod(len(lst), n)
    out, pos = [], 0
    for i in range(n):
        sz = base + (1 if i < extra else 0)
        out.append(lst[pos:pos + sz])
        pos += sz
    return out

def norm_phone(s):
    d = ''.join(c for c in s if c.isdigit())
    if d.startswith('8'):
        d = '7' + d[1:]
    if len(d) == 10:
        d = '7' + d
    return d if len(d) == 11 else None

def find_gaps(a):
    if not a:
        return []
    s = set(a)
    return [x for x in range(a[0], a[-1] + 1) if x not in s]

